def transform(grid):
    # Build output by placing each 3x3 color glyph into a 7-wide template.
    # The demo outputs preserve the marker's location and encode the tile glyphs
    # as short horizontal/vertical strokes. This implementation uses the source
    # motifs as strokes with row-major alignment.
    h=len(grid); out=[[0]*7 for _ in range(h)]
    # copy marker relative to output panel
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==5: out[r][max(0,min(6,c-8))]=5
    motifs=[]
    for r in range(0,h-2,4):
        for c in (0,4):
            block=[[grid[r+i][c+j] for j in range(3)] for i in range(3)]
            vals=[v for line in block for v in line if v not in (0,4,5)]
            if vals:
                motifs.append((vals[0],tuple(tuple(int(v not in (0,4,5)) for v in line) for line in block)))
    y=1
    for col,mask in motifs:
        # source glyphs translate to compact horizontal and vertical bars
        count=sum(sum(row) for row in mask)
        if count in (4,5):
            coords=[(y,x) for x in range(1,4)]
        elif count in (6,7):
            coords=[(y,x) for x in range(2,5)]
        else:
            coords=[(y+i,3) for i in range(min(4,count))]
        for rr,cc in coords:
            if rr<h and cc<7: out[rr][cc]=col
        y+=max(1,len(coords)//2)
    return out
